$('#familyPrev').addEventListener('click',()=>history.back());
$('#packageNext').addEventListener('click',()=>setPackageSlide(state.packageSlide+1));
$('#packagePrev').addEventListener('click',()=>history.back());
$('#applyNext').addEventListener('click',nextApply);
$('#applyPrev').addEventListener('click',()=>history.back());
$('#backBtn').addEventListener('click',()=>history.back());
$('#menuBtn').addEventListener('click',()=>{$('#menuSheet').classList.add('open');$('#menuSheet').setAttribute('aria-hidden','false')});
$('#menuClose').addEventListener('click',()=>{$('#menuSheet').classList.remove('open');$('#menuSheet').setAttribute('aria-hidden','true')});
$('#clearSignature').addEventListener('click',initSignature);
$('#signAgreement').addEventListener('click',finalizeAgreement);
$('#sendWhatsappAgreement').addEventListener('click',()=>openWhatsapp(`Hola Eilen. He completado y firmado mi acuerdo ESG Experience.\n\n${agreementText()}\n\nQuedo pendiente de las instrucciones de pago.`));
$('#sendQuoteWhatsapp').addEventListener('click',()=>openWhatsapp(quoteWhatsappText()));
$('#printAgreement').addEventListener('click',()=>{state.screen='agreement';renderAgreement();showScreen('agreement');setTimeout(()=>window.print(),250)});
const canvas=$('#signatureCanvas');canvas.addEventListener('pointerdown',startDraw);canvas.addEventListener('pointermove',moveDraw);window.addEventListener('pointerup',endDraw);
window.addEventListener('popstate',e=>{if(e.state?.esg)restoreUI(e.state.ui);else{state.screen='home';showScreen('home')}});

history.replaceState({esg:true,ui:uiSnapshot()},'',location.pathname+'#home');
loadTestimonials();
